    const a = aLine.split(' ').map(Number);
    let maxOnes = 0;
    for (let i = 0; i < n; i++) {
      for (let j = i; j < n; j++) {
        let ones = 0;
        for (let k = 0; k < n; k++) {
          if (k >= i && k <= j) {
            ones += (1 - a[k]);
          } else {
            ones += a[k];
          }
        }
        if (ones > maxOnes) {
          maxOnes = ones;
        }
      }
    }
    console.log(maxOnes);
