  input: process.stdin,
  output: process.stdout
});

rl.on('line', (nLine) => {
  const n = parseInt(nLine);
  rl.on('line', (aLine) => {
    const a = aLine.split(' ').map(Number);
    let originalOnes = a.reduce((sum, val) => sum + val, 0);
    let maxGain = -Infinity;
    for (let i = 0; i < n; i++) {
      let currentSum = 0;
      for (let j = i; j < n; j++) {
        currentSum += (a[j] === 0 ? 1 : -1);
        if (currentSum > maxGain) {
          maxGain = currentSum;
        }
      }
    }
    console.log(originalOnes + maxGain);
    rl.close();
  });
});
