  input: process.stdin,
  output: process.stdout
});

rl.on('line', (nLine) => {
  const n = parseInt(nLine);
  rl.on('line', (aLine) => {
    const a = aLine.split(' ').map(Number);
    let maxGain = -Infinity;
    let currentSum = 0;
    for (let i = 0; i < n; i++) {
      const val = a[i] === 1 ? -1 : 1;
      currentSum = Math.max(val, currentSum + val);
      maxGain = Math.max(maxGain, currentSum);
    }
    const originalOnes = a.reduce((acc, x) => acc + x, 0);
    console.log(originalOnes + maxGain);
    rl.close();
  });
});
