const readline = require('readline');
const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout
});

let n;
let arr;

rl.on('line', (line) => {
  if (!n) {
    n = parseInt(line);
  } else {
    arr = line.split(' ').map(Number);
    rl.close();
  }
});

rl.on('close', () => {
  let originalOnes = arr.reduce((acc, val) => acc + val, 0);
  let maxGain = -Infinity;

  for (let i = 0; i < n; i++) {
    let gain = 0;
    for (let j = i; j < n; j++) {
      if (arr[j] === 0) {
        gain += 1;
      } else {
        gain -= 1;
      }
      if (gain > maxGain) {
        maxGain = gain;
      }
    }
  }

  console.log(originalOnes + maxGain);
});
